def lps(s):
    """
    Finds the length of the longest palindromic subsequence in the given string.
    """
    def memoized_lps(s, i, j, memo):
        if i > j:
            return 0
        if i == j:
            return 1
        if (i, j) not in memo:
            if s[i] == s[j]:
                memo[(i, j)] = 2 + memoized_lps(s, i + 1, j - 1, memo)
            else:
                memo[(i, j)] = max(memoized_lps(s, i + 1, j, memo), memoized_lps(s, i, j - 1, memo))
