        return 3
    elif n == 1:
        return 0 + 2 + 3  # Sum of P(0), P(1), P(2)
    elif n == 2:
        return 2 + 3 + 2  # Sum of P(1), P(2), P(3)

    # Initialize the first three values of the Perrin sequence
    a, b, c = 3, 0, 2
    sum_perrin = a + b + c  # Initial sum of the first three Perrin numbers

    # Calculate the sum of Perrin numbers up to P(n)
    for i in range(3, n + 1):
        next_val = a + b  # P(i) = P(i-2) + P(i-3)
        sum_perrin += next_val
        a, b, c = b, c, next_val  # Shift the values for the next iteration

